mapper.select:
SELECT P.pop_idx AS "popIdx", P.sys_se_cd AS "sysSeCd", P.pop_titl AS "popTitl", P.pop_cn AS "popCn", P.bgng_ymd AS "bgngYmd", P.end_ymd AS "endYmd", P.use_yn AS "useYn", P.file_grp_id AS "fileGrpId", P.surv_id AS "survId", P.frst_rgstr_id AS "frstRgstrId", P.frst_reg_dt AS "frstRegDt", S.surv_nm AS "survNm" FROM TN_POP_M001 P LEFT JOIN TN_SURVEY_M001 S ON P.sys_id = S.sys_id AND P.surv_id = S.surv_id WHERE P.sys_id = #{sysId}
AND P.sys_se_cd = #{searchSysSeCd}
AND (P.bgng_ymd <= #{searchEdDate} AND P.end_ymd >= #{searchStDate})
AND P.del_yn = 'N' ORDER BY P.pop_idx DESC

mapper.insert:
INSERT INTO TN_POP_M001 (
    sys_id, sys_se_cd, pop_titl, pop_cn, bgng_ymd, end_ymd, file_grp_id, surv_id, use_yn, del_yn, frst_rgstr_id, frst_reg_dt
) VALUES (
             #{sysId}, #{sysSeCd}, #{popTitl}, #{popCn}, #{bgngYmd}, #{endYmd}, #{fileGrpId}, #{survId}, #{useYn}, 'N', #{userId}, NOW()
         )
